From 748d8fef3bfec6171286a79a8a960f6752b413ee Mon Sep 17 00:00:00 2001
From: Roman Lebedev <lebedev.ri@gmail.com>
Date: Sun, 17 Sep 2017 16:50:53 +0300
Subject: [PATCH] ThreefrDecoder::decodeRawInternal(): don't catch IOException

---
 src/librawspeed/decoders/ThreefrDecoder.cpp | 9 ++-------
 1 file changed, 2 insertions(+), 7 deletions(-)

diff --git a/src/librawspeed/decoders/ThreefrDecoder.cpp b/src/librawspeed/decoders/ThreefrDecoder.cpp
index 7aaf33f..7b46d3b 100644
--- a/src/librawspeed/decoders/ThreefrDecoder.cpp
+++ b/src/librawspeed/decoders/ThreefrDecoder.cpp
@@ -66,14 +66,9 @@ RawImage ThreefrDecoder::decodeRawInternal() {
   mRaw->createData();

   HasselbladDecompressor l(bs, mRaw);
-  int pixelBaseOffset = hints.get("pixelBaseOffset", 0);

-  try {
-    l.decode(pixelBaseOffset);
-  } catch (IOException &e) {
-    mRaw->setError(e.what());
-    // Let's ignore it, it may have delivered somewhat useful data.
-  }
+  int pixelBaseOffset = hints.get("pixelBaseOffset", 0);
+  l.decode(pixelBaseOffset);

   return mRaw;
 }
